import numpy as np
from scipy.optimize import minimize

def lagrange_multipliers(f, g, x0, constraint_value=0):
    def lagrangian(vars):
        x = vars[:-1]
        lam = vars[-1]
        return f(x) + lam * g(x)

    def constraint_eq(vars):
        x = vars[:-1]
        return g(x)

    vars0 = np.append(x0, 0.0)

    cons = {'type': 'eq', 'fun': constraint_eq}
    result = minimize(lagrangian, vars0, constraints=cons, method='SLSQP')

    return result

def f(xy):
    return xy[0]**2 + xy[1]**2

def g(xy):
    return xy[0] + xy[1] - 1

x0 = np.array([0.5, 0.5])
result = lagrange_multipliers(f, g, x0)
print(f"Optimal point: {result.x}")
print(f"Minimum value: {f(result.x)}")
